// AT2: V2Router02 round trip (9 functions) + SwapRouter02 V2-style (AT12, 2 functions)
// ============================================================================

const RT_PATH_A = [_][20]u8{ addr("c02aaa39b223fe8d0a0e5c4f27ead9083c756cc2"), addr("dac17f958d2ee523a2206206994597c13d831ec7") };
const RT_TO = addr("1111111111111111111111111111111111111111");

fn rtPathValues(tokens: []const [20]u8, buf: []AV) []const AV {
    for (tokens, 0..) |t, i| buf[i] = .{ .address = t };
    return buf[0..tokens.len];
}

test "AT2: round trip - swapExactTokensForTokens" {
    const allocator = testing.allocator;
    var path_buf: [2]AV = undefined;
    const values = [_]AV{
        .{ .uint256 = 1000 },
        .{ .uint256 = 900 },
        .{ .array = rtPathValues(&RT_PATH_A, &path_buf) },
        .{ .address = RT_TO },
        .{ .uint256 = 1234567890 },
    };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.swap_exact_tokens_for_tokens, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const swap = switch (decoded.?) {
        .v2_swap_exact_tokens_for_tokens => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 1000), swap.amount_in);
    try testing.expectEqual(@as(u256, 900), swap.amount_out_min);
    try testing.expectEqual(@as(usize, 2), swap.path.len());
    try testing.expectEqualSlices(u8, &RT_PATH_A[0], &swap.path.get(0));
    try testing.expectEqualSlices(u8, &RT_PATH_A[1], &swap.path.get(1));
    try testing.expectEqualSlices(u8, &RT_PATH_A[0], &swap.path.first());
    try testing.expectEqualSlices(u8, &RT_PATH_A[1], &swap.path.last());
    try testing.expectEqualSlices(u8, &RT_TO, &swap.to);
    try testing.expectEqual(@as(?u256, 1234567890), swap.deadline);
}

