test "AT4: V3Path - 1 hop" {
    const allocator = testing.allocator;
    const tokens = [_][20]u8{ RT_TOKEN_IN, RT_TOKEN_OUT };
    const fees = [_]u24{2500};
    const path = try packV3Path(allocator, &tokens, &fees);
    defer allocator.free(path);

    const tuple = [_]AV{
        .{ .bytes = path },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1 },
        .{ .uint256 = 2 },
        .{ .uint256 = 3 },
    };
    const values = [_]AV{.{ .tuple = &tuple }};
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.exact_input, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const swap = switch (decoded.?) {
        .v3_exact_input => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(usize, 1), swap.path.hops());
    try testing.expectEqualSlices(u8, &tokens[0], &swap.path.first());
    try testing.expectEqualSlices(u8, &tokens[1], &swap.path.last());
    const hop0 = swap.path.hop(0);
    try testing.expectEqualSlices(u8, &tokens[0], &hop0.token_a);
    try testing.expectEqual(@as(u24, 2500), hop0.fee);
    try testing.expectEqualSlices(u8, &tokens[1], &hop0.token_b);
}

test "AT4: V3Path - 3 hops" {
    const allocator = testing.allocator;
    const tokens = [_][20]u8{
        RT_TOKEN_IN,
        RT_TOKEN_OUT,
        addr("3333333333333333333333333333333333333333"),
        addr("4444444444444444444444444444444444444444"),
    };
    const fees = [_]u24{ 500, 3000, 100 };
    const path = try packV3Path(allocator, &tokens, &fees);
    defer allocator.free(path);

    const tuple = [_]AV{
        .{ .bytes = path },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1 },
        .{ .uint256 = 2 },
        .{ .uint256 = 3 },
    };
    const values = [_]AV{.{ .tuple = &tuple }};
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.exact_input, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const swap = switch (decoded.?) {
        .v3_exact_input => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(usize, 3), swap.path.hops());
    try testing.expectEqualSlices(u8, &tokens[0], &swap.path.first());
    try testing.expectEqualSlices(u8, &tokens[3], &swap.path.last());
    for (0..3) |i| {
        const hop = swap.path.hop(i);
        try testing.expectEqualSlices(u8, &tokens[i], &hop.token_a);
        try testing.expectEqual(fees[i], hop.fee);
        try testing.expectEqualSlices(u8, &tokens[i + 1], &hop.token_b);
    }
}

fn buildExactInputWithPathLen(allocator: std.mem.Allocator, path_len: usize) ![]u8 {
    const path = try allocator.alloc(u8, path_len);
    defer allocator.free(path);
    @memset(path, 0xAB);
    const tuple = [_]AV{
        .{ .bytes = path },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1 },
        .{ .uint256 = 2 },
        .{ .uint256 = 3 },
    };
    const values = [_]AV{.{ .tuple = &tuple }};
    return abi_encode.encodeFunctionCall(allocator, c.selectors.exact_input, &values);
}

test "AT4: V3Path - rejects malformed path lengths" {
    const allocator = testing.allocator;
    // Valid lengths are 20 + 23k with k >= 1 (43, 66, 89, ...); none of these fit.
    const bad_lengths = [_]usize{ 0, 20, 42, 44, 65, 67 };
    for (bad_lengths) |len| {
        const encoded = try buildExactInputWithPathLen(allocator, len);
        defer allocator.free(encoded);
        try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
    }
}

// ============================================================================
// R1 (spec section 9, amendment H1): every address[] swap path must have at
// least 2 elements, as in UniswapV2Library.sol:63,74 and UR
// V2SwapRouter.sol:75,112. Shorter paths make `decode` null.
// ============================================================================

test "R1: V2Router02 swapExactTokensForTokens - path length 0 and 1 null, length 2 decodes" {
    const allocator = testing.allocator;
    var path_buf: [2]AV = undefined;
    const lengths = [_]usize{ 0, 1, 2 };
    for (lengths) |n| {
        const values = [_]AV{
            .{ .uint256 = 1000 },
            .{ .uint256 = 900 },
            .{ .array = rtPathValues(RT_PATH_A[0..n], &path_buf) },
            .{ .address = RT_TO },
            .{ .uint256 = 1234567890 },
        };
        const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.swap_exact_tokens_for_tokens, &values);
        defer allocator.free(encoded);
        const decoded = c.decode(encoded);
        if (n < 2) {
            try testing.expectEqual(@as(?c.Decoded, null), decoded);
        } else {
            try testing.expect(decoded != null);
        }
    }
}

