test "AT11/B4: fixture - multicall(bytes[]) with typed selfPermit + swap inner calls (0xac9650d8)" {
    const decoded = c.decode(&F_MC_AC9650D8);
    try testing.expect(decoded != null);
    const mc = switch (decoded.?) {
        .multicall => |m| m,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(?u256, null), mc.deadline);
    try testing.expectEqual(@as(?[32]u8, null), mc.previous_blockhash);
    try testing.expectEqual(@as(usize, 2), mc.len());

    var it = mc.iterator();

    // selfPermit(address,uint256,uint256,uint8,bytes32,bytes32) = 0xf3995c67.
    // Expected fields from `cast abi-decode --input
    // "f(address,uint256,uint256,uint8,bytes32,bytes32)"` on the inner call
    // bytes (never from this decoder).
    const call0 = it.next().?;
    const payment0 = switch (call0) {
        .payment => |p| p,
        .swap, .other => return error.WrongVariant,
    };
    const self_permit0 = switch (payment0) {
        .self_permit => |sp| sp,
        else => return error.WrongVariant,
    };
    try testing.expect(self_permit0.kind == .permit);
    try testing.expectEqualSlices(u8, &addr("100a2c7f45fd48e217fdce72e658dc78fd43a100"), &self_permit0.token);
    try testing.expectEqual(@as(u256, 18984161), self_permit0.amount);
    try testing.expectEqual(@as(u256, 1790212006), self_permit0.deadline);
    try testing.expectEqual(@as(u8, 27), self_permit0.v);
    try testing.expectEqualSlices(u8, &word32("dcc450d861cd9fa01281f3973d279c801b9f14887cf2a497946511811c20f368"), &self_permit0.r);
    try testing.expectEqualSlices(u8, &word32("25bbc60c60925ea122edf94bad002a60091171e518b4e2b9c60052bdf452c600"), &self_permit0.s);

    const call1 = it.next().?;
    const swap1 = switch (call1) {
        .swap => |s| s,
        .payment, .other => return error.WrongVariant,
    };
    const inner = switch (swap1) {
        .v3_exact_input_single => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("100a2c7f45fd48e217fdce72e658dc78fd43a100"), &inner.token_in);
    try testing.expectEqualSlices(u8, &addr("dac17f958d2ee523a2206206994597c13d831ec7"), &inner.token_out);
    try testing.expectEqual(@as(u24, 100), inner.fee);
    try testing.expectEqualSlices(u8, &addr("c4498e4ad707164defc3a979d291711f5fd17a7a"), &inner.recipient);
    try testing.expectEqual(@as(?u256, null), inner.deadline);
    try testing.expectEqual(@as(u256, 18984161), inner.amount_in);
    try testing.expectEqual(@as(u256, 25732342), inner.amount_out_minimum);

    try testing.expectEqual(@as(?c.Multicall.Call, null), it.next());
}

