test "AT2/AT3: UR execute round trip - execute(bytes,bytes[],uint256), 5-field legacy layout, all typed commands + unknown + allow-revert" {
    const allocator = testing.allocator;

    const v3_path_tokens = [_][20]u8{ RT_TOKEN_IN, RT_TOKEN_OUT };
    const v3_path = try packV3Path(allocator, &v3_path_tokens, &[_]u24{500});
    defer allocator.free(v3_path);

    const v2_path = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_TOKEN_OUT } };

    const cmd_v3_in = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1000 },
        .{ .uint256 = 990 },
        .{ .bytes = v3_path },
        .{ .boolean = true },
    };
    const in_v3_in = try abi_encode.encodeValues(allocator, &cmd_v3_in);
    defer allocator.free(in_v3_in);

    const cmd_v3_out = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 500 },
        .{ .uint256 = 520 },
        .{ .bytes = v3_path },
        .{ .boolean = false },
    };
    const in_v3_out = try abi_encode.encodeValues(allocator, &cmd_v3_out);
    defer allocator.free(in_v3_out);

    const cmd_v2_in = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 200 },
        .{ .uint256 = 190 },
        .{ .array = &v2_path },
        .{ .boolean = true },
    };
    const in_v2_in = try abi_encode.encodeValues(allocator, &cmd_v2_in);
    defer allocator.free(in_v2_in);

    const cmd_v2_out = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 300 },
        .{ .uint256 = 310 },
        .{ .array = &v2_path },
        .{ .boolean = false },
    };
    const in_v2_out = try abi_encode.encodeValues(allocator, &cmd_v2_out);
    defer allocator.free(in_v2_out);

    const cmd_wrap = [_]AV{ .{ .address = RT_RECIPIENT }, .{ .uint256 = 1000000 } };
    const in_wrap = try abi_encode.encodeValues(allocator, &cmd_wrap);
    defer allocator.free(in_wrap);

    const cmd_unwrap = [_]AV{ .{ .address = RT_RECIPIENT }, .{ .uint256 = 2000000 } };
    const in_unwrap = try abi_encode.encodeValues(allocator, &cmd_unwrap);
    defer allocator.free(in_unwrap);

    const cmd_sweep = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_RECIPIENT }, .{ .uint256 = 1 } };
    const in_sweep = try abi_encode.encodeValues(allocator, &cmd_sweep);
    defer allocator.free(in_sweep);

    const cmd_transfer = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_RECIPIENT }, .{ .uint256 = 42 } };
    const in_transfer = try abi_encode.encodeValues(allocator, &cmd_transfer);
    defer allocator.free(in_transfer);

    const cmd_pay_portion = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_RECIPIENT }, .{ .uint256 = 5000 } };
    const in_pay_portion = try abi_encode.encodeValues(allocator, &cmd_pay_portion);
    defer allocator.free(in_pay_portion);

    const unknown_payload = [_]u8{ 0xDE, 0xAD, 0xBE, 0xEF };

    // commands: v3_in, v3_out, v2_in, v2_out, wrap, unwrap, sweep, transfer,
    // pay_portion, and an unknown type (0x02) with allow_revert set.
    const commands = [_]u8{
        c.command_types.v3_swap_exact_in,
        c.command_types.v3_swap_exact_out,
        c.command_types.v2_swap_exact_in,
        c.command_types.v2_swap_exact_out,
        c.command_types.wrap_eth,
        c.command_types.unwrap_weth,
        c.command_types.sweep,
        c.command_types.transfer,
        c.command_types.pay_portion,
        0x0f | c.command_types.flag_allow_revert,
    };

    const inputs = [_]AV{
        .{ .bytes = in_v3_in },
        .{ .bytes = in_v3_out },
        .{ .bytes = in_v2_in },
        .{ .bytes = in_v2_out },
        .{ .bytes = in_wrap },
        .{ .bytes = in_unwrap },
        .{ .bytes = in_sweep },
        .{ .bytes = in_transfer },
        .{ .bytes = in_pay_portion },
        .{ .bytes = &unknown_payload },
    };

    const values = [_]AV{
        .{ .bytes = &commands },
        .{ .array = &inputs },
        .{ .uint256 = 1790300000 },
    };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(?u256, 1790300000), ur.deadline);
    try testing.expectEqualSlices(u8, &commands, ur.commands);

    var it = ur.iterator();

    const cmd0 = it.next().?;
    try testing.expectEqual(false, cmd0.allow_revert);
    const p0 = switch (cmd0.payload) {
        .v3_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &RT_RECIPIENT, &p0.recipient);
    try testing.expectEqual(@as(u256, 1000), p0.amount_in);
    try testing.expectEqual(@as(u256, 990), p0.amount_out_min);
    try testing.expectEqual(true, p0.payer_is_user);
    try testing.expectEqual(@as(?c.U256Array, null), p0.min_hop_price_x36);
    try testing.expectEqualSlices(u8, &v3_path_tokens[0], &p0.path.first());
    try testing.expectEqualSlices(u8, &v3_path_tokens[1], &p0.path.last());

    const cmd1 = it.next().?;
    const p1 = switch (cmd1.payload) {
        .v3_swap_exact_out => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 500), p1.amount_out);
    try testing.expectEqual(@as(u256, 520), p1.amount_in_max);
    try testing.expectEqual(false, p1.payer_is_user);

    const cmd2 = it.next().?;
    const p2 = switch (cmd2.payload) {
        .v2_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 200), p2.amount_in);
