    const cmd5 = it.next().?;
    const p5 = switch (cmd5.payload) {
        .unwrap_weth => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 2000000), p5.amount);

    const cmd6 = it.next().?;
    const p6 = switch (cmd6.payload) {
        .sweep => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &RT_TOKEN_IN, &p6.token);
    try testing.expectEqualSlices(u8, &RT_RECIPIENT, &p6.recipient);
    try testing.expectEqual(@as(u256, 1), p6.amount);

    const cmd7 = it.next().?;
