    try testing.expectEqualSlices(u8, &unknown_payload, p9.input);

    try testing.expectEqual(@as(?c.Command, null), it.next());
}

test "AT2/AT3/AT6: UR execute round trip - execute(bytes,bytes[]) no deadline, 6-field layout with minHopPriceX36" {
    const allocator = testing.allocator;

    const v3_path_tokens = [_][20]u8{ RT_TOKEN_IN, RT_TOKEN_OUT, addr("3333333333333333333333333333333333333333") };
    const v3_path = try packV3Path(allocator, &v3_path_tokens, &[_]u24{ 500, 3000 });
    defer allocator.free(v3_path);

    const min_hop = [_]AV{ .{ .uint256 = 111 }, .{ .uint256 = 222 } };
    const cmd_v3_in = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 7000 },
        .{ .uint256 = 6900 },
        .{ .bytes = v3_path },
        .{ .boolean = true },
        .{ .array = &min_hop },
    };
    const in_v3_in = try abi_encode.encodeValues(allocator, &cmd_v3_in);
    defer allocator.free(in_v3_in);

    const v2_path = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_TOKEN_OUT } };
    const min_hop_v2 = [_]AV{.{ .uint256 = 333 }};
    const cmd_v2_out = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 4000 },
        .{ .uint256 = 4100 },
        .{ .array = &v2_path },
        .{ .boolean = false },
        .{ .array = &min_hop_v2 },
    };
    const in_v2_out = try abi_encode.encodeValues(allocator, &cmd_v2_out);
    defer allocator.free(in_v2_out);

    const commands = [_]u8{ c.command_types.v3_swap_exact_in, c.command_types.v2_swap_exact_out };
    const inputs = [_]AV{ .{ .bytes = in_v3_in }, .{ .bytes = in_v2_out } };
    const values = [_]AV{
        .{ .bytes = &commands },
        .{ .array = &inputs },
    };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(?u256, null), ur.deadline);

    var it = ur.iterator();
    const cmd0 = it.next().?;
    const p0 = switch (cmd0.payload) {
        .v3_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 7000), p0.amount_in);
    try testing.expect(p0.min_hop_price_x36 != null);
    try testing.expectEqual(@as(usize, 2), p0.min_hop_price_x36.?.len());
    try testing.expectEqual(@as(u256, 111), p0.min_hop_price_x36.?.get(0));
    try testing.expectEqual(@as(u256, 222), p0.min_hop_price_x36.?.get(1));

    const cmd1 = it.next().?;
    const p1 = switch (cmd1.payload) {
        .v2_swap_exact_out => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 4000), p1.amount_out);
    try testing.expect(p1.min_hop_price_x36 != null);
    try testing.expectEqual(@as(usize, 1), p1.min_hop_price_x36.?.len());
    try testing.expectEqual(@as(u256, 333), p1.min_hop_price_x36.?.get(0));

    try testing.expectEqual(@as(?c.Command, null), it.next());
}

