// ============================================================================

test "AT8: attack - array offset points past the end of data" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(c.selectors.swap_exact_tokens_for_tokens);
    try b.w(1000); // amount_in
    try b.w(900); // amount_out_min
    try b.w(0xFFFFFFFF); // path offset: far past the end
    try b.wAddr(RT_TO); // to
    try b.w(123); // deadline
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(data));
}

test "AT8: attack - array length = 2^256-1" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(c.selectors.swap_exact_tokens_for_tokens);
    try b.w(1000);
    try b.w(900);
    try b.w(0xa0); // path offset: valid, points right after the static head
    try b.wAddr(RT_TO);
    try b.w(123);
    try b.w(std.math.maxInt(u256)); // path array length: 2^256-1
    try b.wAddr(RT_PATH_A[0]);
    try b.wAddr(RT_PATH_A[1]);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(data));
}

test "AT8: attack - offset + length overflows when added" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(c.selectors.swap_exact_tokens_for_tokens);
    try b.w(1000);
    try b.w(900);
    try b.w(0xa0); // path offset: valid, points right after the 5-word head
    try b.wAddr(RT_TO);
    try b.w(123);
    // The length word lives exactly at the offset position (0xa0 bytes into
    // the args, i.e. right here). Its value is chosen so that
    // (offset + length) overflows the u256 domain if computed with an
    // unchecked `+`: offset (0xa0 = 160) + length wraps past 2^256. A
    // correct implementation must bound-check without doing this raw add.
    try b.w(std.math.maxInt(u256) - 16);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(data));
}

test "AT8: attack - dirty address padding" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(c.selectors.swap_exact_tokens_for_tokens);
    try b.w(1000);
    try b.w(900);
    try b.w(0xa0);
    // `to` word: real address in the low 20 bytes, but a nonzero byte in the
    // padding region that real ABI-encoded calldata always zeros.
    var dirty: [32]u8 = @splat(0);
    dirty[0] = 0x01; // dirty high padding byte
    @memcpy(dirty[12..32], &RT_TO);
    try b.wRaw(dirty);
    try b.w(123);
    try b.w(2); // path length
    try b.wAddr(RT_PATH_A[0]);
    try b.wAddr(RT_PATH_A[1]);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(data));
}

