test "AT8: attack - uint24 fee with high bits set" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(c.selectors.exact_input_single);
    try b.wAddr(RT_TOKEN_IN);
    try b.wAddr(RT_TOKEN_OUT);
    // fee word: uint24 only occupies the low 3 bytes; set a bit above that.
    try b.wRaw(blk: {
        var word: [32]u8 = @splat(0);
        word[28] = 0x01; // bit 24 set: outside uint24's range
        word[30] = 0x01; // fee = 500 (0x01f4) in the low 3 bytes
        word[31] = 0xf4;
        break :blk word;
    });
    try b.wAddr(RT_RECIPIENT);
    try b.w(999); // deadline
    try b.w(1000); // amount_in
    try b.w(900); // amount_out_minimum
    try b.w(0); // sqrt_price_limit_x96
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(data));
}

