// ============================================================================
// AT7: hostile input - every prefix length, and 1,000 single-byte mutations
// per fixture, must return null or a value and never panic.
// ============================================================================

test "AT7: hostile input - every prefix of every fixture" {
    for (all_fixtures) |data| {
        var len: usize = 0;
        while (len <= data.len) : (len += 1) {
            if (c.decode(data[0..len])) |d| walkDecoded(d);
        }
    }
}

test "AT7: hostile input - 1,000 single-byte mutations per fixture, fixed seed" {
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xC0FFEE_D00D_1234);
    const rnd = prng.random();

    for (all_fixtures) |data| {
        if (data.len == 0) continue;
        const mutated = try allocator.alloc(u8, data.len);
        defer allocator.free(mutated);

        var i: usize = 0;
        while (i < 1000) : (i += 1) {
            @memcpy(mutated, data);
            const idx = rnd.uintLessThan(usize, data.len);
            mutated[idx] = rnd.int(u8);
            if (c.decode(mutated)) |d| walkDecoded(d);
        }
    }
}

