test "B3: UR fixture - commands 0x02,0x0c,0x10,0x0b (typed permit2_transfer_from, unwrap_weth, v4_swap, wrap_eth)" {
    const decoded = c.decode(&F_UR_CMD_02);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(?u256, 1790181043), ur.deadline);
    try testing.expectEqualSlices(u8, &[_]u8{ 0x02, 0x0c, 0x10, 0x0b }, ur.commands);

    var it = ur.iterator();

    const c0 = it.next().?;
    const transfer_from = switch (c0.payload) {
        .permit2_transfer_from => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("c02aaa39b223fe8d0a0e5c4f27ead9083c756cc2"), &transfer_from.token);
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000002"), &transfer_from.recipient);
    try testing.expectEqual(@as(u160, 29012181416544728), transfer_from.amount);

    const c1 = it.next().?;
    const unwrap1 = switch (c1.payload) {
        .unwrap_weth => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000002"), &unwrap1.recipient);
    try testing.expectEqual(@as(u256, 29012181416544728), unwrap1.amount);

    const c2 = it.next().?;
    const plan2 = switch (c2.payload) {
        .v4_swap => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &[_]u8{ 0x08, 0x0c, 0x0f }, plan2.actions);
    var ait = plan2.iterator();
    const a0 = ait.next().?;
    const swap_out = switch (a0.payload) {
        .swap_exact_out_single => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000000"), &swap_out.pool_key.currency0);
    try testing.expectEqualSlices(u8, &addr("d3ddb098a529a14d920203ed5015482c9226f9b9"), &swap_out.pool_key.currency1);
    try testing.expectEqual(@as(u24, 2500), swap_out.pool_key.fee);
    try testing.expectEqual(@as(i24, 25), swap_out.pool_key.tick_spacing);
    try testing.expectEqual(true, swap_out.zero_for_one);
    try testing.expectEqual(@as(u128, 1993877407862377097924), swap_out.amount_out);
    try testing.expectEqual(@as(u128, 29012181416544728), swap_out.amount_in_maximum);
    try testing.expectEqual(@as(usize, 0), swap_out.hook_data.len);

    const a1 = ait.next().?;
    const settle_all2 = switch (a1.payload) {
        .settle_all => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000000"), &settle_all2.currency);
    try testing.expectEqual(@as(u256, 29012181416544728), settle_all2.amount);

    const a2 = ait.next().?;
    const take_all2 = switch (a2.payload) {
        .take_all => |t| t,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("d3ddb098a529a14d920203ed5015482c9226f9b9"), &take_all2.currency);
    try testing.expectEqual(@as(u256, 1993877407862377097924), take_all2.amount);
    try testing.expectEqual(@as(?c.v4.Action, null), ait.next());

    const c3 = it.next().?;
    const wrap3 = switch (c3.payload) {
        .wrap_eth => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000001"), &wrap3.recipient);
    try testing.expectEqual(@as(u256, 57896044618658097711785492504343953926634992332820282019728792003956564819968), wrap3.amount);
    try testing.expectEqual(@as(?c.Command, null), it.next());
}

