// ============================================================================
// B3/Wave A #2: uniswap_v1 (pre-V4) dialect real fixtures. Same 0x00-0x0e
// commands as `.uniswap`; 0x10-0x20 and 0x22 stay `.other`; mask is 0x3f.
// ============================================================================

fn expectUrV1(data: []const u8, expected_commands: []const u8, expected_tags: []const std.meta.Tag(c.Command.Payload)) !void {
    const decoded = c.decodeFor(.uniswap_ur_v1, data);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expect(ur.dialect == .uniswap_v1);
    try testing.expectEqualSlices(u8, expected_commands, ur.commands);
    var it = ur.iterator();
    for (expected_tags) |tag| {
        const cmd = it.next() orelse return error.MissingCommand;
        try testing.expectEqual(tag, std.meta.activeTag(cmd.payload));
    }
    try testing.expectEqual(@as(?c.Command, null), it.next());
}

