test "B3: round trip - PERMIT2_PERMIT_BATCH (0x03), 2 details" {
    const allocator = testing.allocator;
    const details = [_]AV{
        .{ .tuple = &[_]AV{
            .{ .address = RT_TOKEN_IN },
            .{ .uint256 = 1000 },
            .{ .uint256 = 2000000000 },
            .{ .uint256 = 1 },
