test "B3: round trip - EXECUTE_SUB_PLAN (0x21), nested 0x21 at depth 2 is .other" {
    const allocator = testing.allocator;
    const v3_path_tokens = [_][20]u8{ RT_TOKEN_IN, RT_TOKEN_OUT };
    const v3_path = try packV3Path(allocator, &v3_path_tokens, &[_]u24{3000});
    defer allocator.free(v3_path);
    const cmd_v3_in = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 7000 },
        .{ .uint256 = 6900 },
        .{ .bytes = v3_path },
        .{ .boolean = false },
    };
    const in_v3_in = try abi_encode.encodeValues(allocator, &cmd_v3_in);
    defer allocator.free(in_v3_in);

    const depth2_payload = [_]u8{ 0xC0, 0xFF, 0xEE };
    const sub_commands = [_]u8{ 0x00, 0x21 };
    const sub_inputs = [_]AV{
        .{ .bytes = in_v3_in },
        .{ .bytes = &depth2_payload },
    };
    const sub_values = [_]AV{ .{ .bytes = &sub_commands }, .{ .array = &sub_inputs } };
    const sub_plan_bytes = try abi_encode.encodeValues(allocator, &sub_values);
    defer allocator.free(sub_plan_bytes);

    const commands = [_]u8{0x21};
    const inputs = [_]AV{.{ .bytes = sub_plan_bytes }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);

    const decoded = c.decode(encoded);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(false, ur.is_sub_plan);
    var it = ur.iterator();
    const cmd0 = it.next().?;
    const sub = switch (cmd0.payload) {
        .execute_sub_plan => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(true, sub.is_sub_plan);
    try testing.expectEqual(@as(?u256, null), sub.deadline);
    try testing.expectEqualSlices(u8, &sub_commands, sub.commands);

    var sub_it = sub.iterator();
    const sc0 = sub_it.next().?;
    const swap = switch (sc0.payload) {
        .v3_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &RT_RECIPIENT, &swap.recipient);
    try testing.expectEqual(@as(u256, 7000), swap.amount_in);

    const sc1 = sub_it.next().?;
    const other1 = switch (sc1.payload) {
        .other => |o| o,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u8, 0x21), other1.command_type);
    try testing.expectEqualSlices(u8, &depth2_payload, other1.input);
    try testing.expectEqual(@as(?c.Command, null), sub_it.next());
    try testing.expectEqual(@as(?c.Command, null), it.next());
}

test "B3: round trip - PancakeSwap stable swap 0x22/0x23 under .pancake dialect" {
    const allocator = testing.allocator;
    const path = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .address = RT_TOKEN_OUT } };
    const flags = [_]AV{ .{ .uint256 = 1 }, .{ .uint256 = 2 } };

    const cmd_in = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 5000 },
        .{ .uint256 = 4900 },
        .{ .array = &path },
        .{ .array = &flags },
        .{ .boolean = true },
    };
    const in_bytes = try abi_encode.encodeValues(allocator, &cmd_in);
    defer allocator.free(in_bytes);

    const cmd_out = [_]AV{
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 3000 },
        .{ .uint256 = 3100 },
        .{ .array = &path },
        .{ .array = &flags },
        .{ .boolean = false },
    };
    const out_bytes = try abi_encode.encodeValues(allocator, &cmd_out);
    defer allocator.free(out_bytes);

    const commands = [_]u8{ 0x22, 0x23 };
    const inputs = [_]AV{ .{ .bytes = in_bytes }, .{ .bytes = out_bytes } };
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);

    // Under .pancake, 0x22/0x23 are typed stable swaps.
    const decoded_pancake = c.decodeFor(.pancake_ur, encoded);
    try testing.expect(decoded_pancake != null);
    const ur_pancake = switch (decoded_pancake.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    try testing.expect(ur_pancake.dialect == .pancake);
    var it_pancake = ur_pancake.iterator();

    const c0 = it_pancake.next().?;
    const swap_in = switch (c0.payload) {
        .stable_swap_exact_in => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &RT_RECIPIENT, &swap_in.recipient);
    try testing.expectEqual(@as(u256, 5000), swap_in.amount0);
    try testing.expectEqual(@as(u256, 4900), swap_in.amount1);
    try testing.expectEqual(@as(usize, 2), swap_in.path.len());
    try testing.expectEqualSlices(u8, &RT_TOKEN_IN, &swap_in.path.first());
    try testing.expectEqualSlices(u8, &RT_TOKEN_OUT, &swap_in.path.last());
    try testing.expectEqual(@as(usize, 2), swap_in.flags.len());
    try testing.expectEqual(@as(u256, 1), swap_in.flags.get(0));
    try testing.expectEqual(@as(u256, 2), swap_in.flags.get(1));
    try testing.expectEqual(true, swap_in.payer_is_user);

    const c1 = it_pancake.next().?;
    const swap_out = switch (c1.payload) {
        .stable_swap_exact_out => |s| s,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 3000), swap_out.amount0);
    try testing.expectEqual(@as(u256, 3100), swap_out.amount1);
    try testing.expectEqual(false, swap_out.payer_is_user);

    // Under .uniswap and .uniswap_v1, 0x22/0x23 are never stable swaps.
    const decoded_uniswap = c.decode(encoded);
    try testing.expect(decoded_uniswap != null);
    const ur_uniswap = switch (decoded_uniswap.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    var it_uniswap = ur_uniswap.iterator();
    const cmd_u0 = it_uniswap.next().?;
    try testing.expect(std.meta.activeTag(cmd_u0.payload) != .stable_swap_exact_in);
    const cmd_u1 = it_uniswap.next().?;
    try testing.expect(std.meta.activeTag(cmd_u1.payload) != .stable_swap_exact_out);
}

test "B1/B3: round trip - V4_SWAP (0x10) dialect matrix: typed under .uniswap, .other under .uniswap_v1/.pancake" {
    const allocator = testing.allocator;
    // Minimal valid V4 plan: one SETTLE_ALL action (currency, uint256 amount).
    const settle_all_params = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .uint256 = 12345 } };
    const settle_all_bytes = try abi_encode.encodeValues(allocator, &settle_all_params);
    defer allocator.free(settle_all_bytes);

    const v4_actions = [_]u8{0x0c};
    const v4_params = [_]AV{.{ .bytes = settle_all_bytes }};
    const v4_values = [_]AV{ .{ .bytes = &v4_actions }, .{ .array = &v4_params } };
    const v4_input = try abi_encode.encodeValues(allocator, &v4_values);
    defer allocator.free(v4_input);

    const commands = [_]u8{0x10};
    const inputs = [_]AV{.{ .bytes = v4_input }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);

    const decoded_uniswap = c.decodeFor(.uniswap, encoded);
    try testing.expect(decoded_uniswap != null);
    const ur_uniswap = switch (decoded_uniswap.?) {
        .universal_router_execute => |u| u,
        else => return error.WrongVariant,
    };
    var it_uniswap = ur_uniswap.iterator();
    const c0 = it_uniswap.next().?;
    const plan = switch (c0.payload) {
        .v4_swap => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &v4_actions, plan.actions);

    // Dialects are reached through `decodeFor`'s `Router`. Each router pairs
    // with the dialect its `UniversalRouterExecute.dialect` should come back as.
    const router_dialect_cases = .{
        .{ c.Router.uniswap_ur_v1, c.UrDialect.uniswap_v1 },
        .{ c.Router.pancake_ur, c.UrDialect.pancake },
    };
    inline for (router_dialect_cases) |case| {
        const router = case[0];
        const expected_dialect = case[1];
        const decoded = c.decodeFor(router, encoded);
        try testing.expect(decoded != null);
        const ur = switch (decoded.?) {
            .universal_router_execute => |u| u,
            else => return error.WrongVariant,
        };
        try testing.expect(ur.dialect == expected_dialect);
        var it = ur.iterator();
        const cmd0 = it.next().?;
        const other0 = switch (cmd0.payload) {
            .other => |o| o,
            else => return error.WrongVariant,
        };
        try testing.expectEqual(@as(u8, 0x10), other0.command_type);
    }
}

// ============================================================================
// B4: multicall typed payment round trips. SwapRouter/SwapRouter02
// PeripheryPayments*/SelfPermit helpers (spec Wave A #3).
// ============================================================================

fn wrapAsMulticall(allocator: std.mem.Allocator, sel4: [4]u8, values: []const AV) ![]u8 {
    const inner_call = try abi_encode.encodeFunctionCall(allocator, sel4, values);
    defer allocator.free(inner_call);
    const calls = [_]AV{.{ .bytes = inner_call }};
    const outer_values = [_]AV{.{ .array = &calls }};
    return abi_encode.encodeFunctionCall(allocator, c.selectors.multicall, &outer_values);
}

fn firstPaymentCall(decoded: ?c.Decoded) !c.Multicall.Payment {
    try testing.expect(decoded != null);
    const mc = switch (decoded.?) {
        .multicall => |m| m,
        else => return error.WrongVariant,
    };
    var it = mc.iterator();
    const call0 = it.next().?;
    return switch (call0) {
        .payment => |p| p,
        .swap, .other => error.WrongVariant,
    };
}

