    const allocator = testing.allocator;

    // unwrapWETH9(uint256) = 0x49616997: no recipient argument (pays msg.sender).
    {
        const values = [_]AV{.{ .uint256 = 1000 }};
        const encoded = try wrapAsMulticall(allocator, .{ 0x49, 0x61, 0x69, 0x97 }, &values);
