        const payment = try firstPaymentCall(c.decode(encoded));
        const sweep = switch (payment) {
            .sweep_token => |s| s,
            else => return error.WrongVariant,
        };
        try testing.expectEqualSlices(u8, &RT_TOKEN_IN, &sweep.token);
        try testing.expectEqual(@as(u256, 111), sweep.amount_minimum);
        try testing.expectEqual(@as(?[20]u8, null), sweep.recipient);
    }
    // sweepToken(address,uint256,address) = 0xdf2ab5bb: with recipient.
    {
        const values = [_]AV{ .{ .address = RT_TOKEN_OUT }, .{ .uint256 = 222 }, .{ .address = RT_RECIPIENT } };
        const encoded = try wrapAsMulticall(allocator, .{ 0xdf, 0x2a, 0xb5, 0xbb }, &values);
        defer allocator.free(encoded);
        const payment = try firstPaymentCall(c.decode(encoded));
        const sweep = switch (payment) {
            .sweep_token => |s| s,
            else => return error.WrongVariant,
        };
        try testing.expectEqualSlices(u8, &RT_TOKEN_OUT, &sweep.token);
        try testing.expectEqual(@as(u256, 222), sweep.amount_minimum);
        try testing.expect(sweep.recipient != null);
        try testing.expectEqualSlices(u8, &RT_RECIPIENT, &sweep.recipient.?);
    }
}

