test "B4: multicall round trip - refundETH, wrapETH, pull" {
    const allocator = testing.allocator;

    // refundETH() = 0x12210e8a: no arguments.
    {
        const values = [_]AV{};
        const encoded = try wrapAsMulticall(allocator, .{ 0x12, 0x21, 0x0e, 0x8a }, &values);
        defer allocator.free(encoded);
        const payment = try firstPaymentCall(c.decode(encoded));
        try testing.expect(payment == .refund_eth);
    }
    // wrapETH(uint256) = 0x1c58db4f.
    {
        const values = [_]AV{.{ .uint256 = 777777 }};
        const encoded = try wrapAsMulticall(allocator, .{ 0x1c, 0x58, 0xdb, 0x4f }, &values);
        defer allocator.free(encoded);
        const payment = try firstPaymentCall(c.decode(encoded));
        const wrap = switch (payment) {
            .wrap_eth => |w| w,
            else => return error.WrongVariant,
        };
        try testing.expectEqual(@as(u256, 777777), wrap.value);
    }
    // pull(address,uint256) = 0xf2d5d56b.
    {
        const values = [_]AV{ .{ .address = RT_TOKEN_IN }, .{ .uint256 = 888888 } };
        const encoded = try wrapAsMulticall(allocator, .{ 0xf2, 0xd5, 0xd5, 0x6b }, &values);
        defer allocator.free(encoded);
        const payment = try firstPaymentCall(c.decode(encoded));
        const pull = switch (payment) {
            .pull => |p| p,
            else => return error.WrongVariant,
        };
        try testing.expectEqualSlices(u8, &RT_TOKEN_IN, &pull.token);
        try testing.expectEqual(@as(u256, 888888), pull.value);
    }
}

fn expectSelfPermitKind(allocator: std.mem.Allocator, sel4: [4]u8, comptime kind_name: []const u8) !void {
    const r = [_]u8{0x1B} ** 32;
    const s = [_]u8{0x2C} ** 32;
    const values = [_]AV{
        .{ .address = RT_TOKEN_IN },
        .{ .uint256 = 5555 },
        .{ .uint256 = 1790600000 },
        .{ .uint256 = 28 },
        .{ .fixed_bytes = .{ .data = r, .len = 32 } },
        .{ .fixed_bytes = .{ .data = s, .len = 32 } },
    };
    const encoded = try wrapAsMulticall(allocator, sel4, &values);
    defer allocator.free(encoded);
    const payment = try firstPaymentCall(c.decode(encoded));
    const self_permit = switch (payment) {
        .self_permit => |sp| sp,
        else => return error.WrongVariant,
    };
    try testing.expect(self_permit.kind == @field(@TypeOf(self_permit.kind), kind_name));
    try testing.expectEqualSlices(u8, &RT_TOKEN_IN, &self_permit.token);
    try testing.expectEqual(@as(u256, 5555), self_permit.amount);
    try testing.expectEqual(@as(u256, 1790600000), self_permit.deadline);
    try testing.expectEqual(@as(u8, 28), self_permit.v);
    try testing.expectEqualSlices(u8, &r, &self_permit.r);
    try testing.expectEqualSlices(u8, &s, &self_permit.s);
}

test "B4: multicall round trip - selfPermit, all four kinds" {
    const allocator = testing.allocator;
    try expectSelfPermitKind(allocator, .{ 0xf3, 0x99, 0x5c, 0x67 }, "permit"); // selfPermit
    try expectSelfPermitKind(allocator, .{ 0xc2, 0xe3, 0x14, 0x0a }, "permit_if_necessary"); // selfPermitIfNecessary
    try expectSelfPermitKind(allocator, .{ 0x46, 0x59, 0xa4, 0x94 }, "allowed"); // selfPermitAllowed
    try expectSelfPermitKind(allocator, .{ 0xa4, 0xa7, 0x8f, 0x0c }, "allowed_if_necessary"); // selfPermitAllowedIfNecessary
}

// ============================================================================
// B5: crafted rejections for the new typed payloads (hostile input, spec
// section 4 "Known limits" extended to the wave-2 types).
// ============================================================================

test "B5: attack - PERMIT2_TRANSFER_FROM uint160 amount with high bits set" {
    const allocator = testing.allocator;
    const cmd = [_]AV{
        .{ .address = RT_TOKEN_IN },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 123456789 },
    };
    const in_bytes = try abi_encode.encodeValues(allocator, &cmd);
    defer allocator.free(in_bytes);
    // Dirty the top byte of the amount word (bytes [64:96), high 12 bytes
    // must be zero for a clean uint160).
    in_bytes[64] = 0xFF;

    const commands = [_]u8{0x02};
    const inputs = [_]AV{.{ .bytes = in_bytes }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
}

test "B5: attack - PERMIT2_PERMIT uint48 expiration with high bits set" {
    const allocator = testing.allocator;
