}

test "B5: attack - PERMIT2_PERMIT_BATCH details array offset out of bounds" {
    const allocator = testing.allocator;
    const details = [_]AV{.{ .tuple = &[_]AV{
        .{ .address = RT_TOKEN_IN },
        .{ .uint256 = 1000 },
        .{ .uint256 = 2000000000 },
        .{ .uint256 = 1 },
    } }};
    const permit_batch = AV{ .tuple = &[_]AV{
        .{ .array = &details },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1790500000 },
    } };
    const sig = [_]u8{0xCD} ** 65;
    const cmd = [_]AV{ permit_batch, .{ .bytes = &sig } };
    const in_bytes = try abi_encode.encodeValues(allocator, &cmd);
    defer allocator.free(in_bytes);

    // word0 of `in_bytes` is the offset to the PermitBatch tuple; the first
    // field of that tuple is the offset to `details`. Corrupt it to a huge
    // value so it lands past the end of the command input.
    const tuple_offset: usize = @intCast(uint256.fromBigEndianBytes(in_bytes[0..32].*));
    @memset(in_bytes[tuple_offset..][0..32], 0xFF);

    const commands = [_]u8{0x03};
    const inputs = [_]AV{.{ .bytes = in_bytes }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
}

test "B5: attack - PERMIT2_PERMIT signature length claims past the end of data" {
    const allocator = testing.allocator;
    const sig = [_]u8{0xEF} ** 65;
    const cmd = [_]AV{
        .{ .address = RT_TOKEN_IN },
        .{ .uint256 = 999999 },
        .{ .uint256 = 1800000000 },
        .{ .uint256 = 3 },
        .{ .address = RT_RECIPIENT },
        .{ .uint256 = 1790500000 },
        .{ .bytes = &sig },
    };
    const in_bytes = try abi_encode.encodeValues(allocator, &cmd);
    defer allocator.free(in_bytes);

    // word 6 (bytes [192:224)) is the offset to the signature bytes; the
    // word at that offset is its length. Corrupt the length to a huge value.
    const sig_offset: usize = @intCast(uint256.fromBigEndianBytes(in_bytes[192..224].*));
    @memset(in_bytes[sig_offset..][0..32], 0xFF);

    const commands = [_]u8{0x0a};
    const inputs = [_]AV{.{ .bytes = in_bytes }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
}

test "B5: attack - EXECUTE_SUB_PLAN commands.len != inputs.len" {
    const allocator = testing.allocator;
    // commands has 2 entries, inputs has only 1: a structural mismatch that
    // must reject the whole sub-plan (and so the whole outer execute).
    const sub_commands = [_]u8{ 0x00, 0x00 };
    const in_v3_placeholder = [_]u8{ 0x00, 0x01, 0x02, 0x03 };
    const sub_inputs = [_]AV{.{ .bytes = &in_v3_placeholder }};
    const sub_values = [_]AV{ .{ .bytes = &sub_commands }, .{ .array = &sub_inputs } };
    const sub_plan_bytes = try abi_encode.encodeValues(allocator, &sub_values);
    defer allocator.free(sub_plan_bytes);

    const commands = [_]u8{0x21};
    const inputs = [_]AV{.{ .bytes = sub_plan_bytes }};
    const values = [_]AV{ .{ .bytes = &commands }, .{ .array = &inputs }, .{ .uint256 = 1790300000 } };
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.execute_deadline, &values);
    defer allocator.free(encoded);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
}

test "B5: attack - multicall selfPermit uint8 v with high bits set" {
    const allocator = testing.allocator;
    const r = [_]u8{0x1B} ** 32;
    const s = [_]u8{0x2C} ** 32;
    const values = [_]AV{
        .{ .address = RT_TOKEN_IN },
        .{ .uint256 = 5555 },
        .{ .uint256 = 1790600000 },
        .{ .uint256 = 27 }, // v: word index 3, byte offset 4 + 3*32 = 100
        .{ .fixed_bytes = .{ .data = r, .len = 32 } },
        .{ .fixed_bytes = .{ .data = s, .len = 32 } },
    };
    const inner_call = try abi_encode.encodeFunctionCall(allocator, .{ 0xf3, 0x99, 0x5c, 0x67 }, &values);
    defer allocator.free(inner_call);
    // Dirty the high byte of the `v` word: it must be all-zero except the
    // last byte for a clean uint8.
    inner_call[100] = 0xFF;

    const calls = [_]AV{.{ .bytes = inner_call }};
    const outer_values = [_]AV{.{ .array = &calls }};
    const encoded = try abi_encode.encodeFunctionCall(allocator, c.selectors.multicall, &outer_values);
    defer allocator.free(encoded);
    try testing.expectEqual(@as(?c.Decoded, null), c.decode(encoded));
}
